    "edu.title": "Why does this simulator exist?",
    "edu.intro": "When you want to install Linux alongside Windows (dual boot), you need to make room on the disk. Windows has a built-in feature called \"Shrink Volume\" that reduces the C: partition without deleting data. However, the numbers it shows can be confusing:",
    "edu.point1.title": "The numbers are in MB (megabytes)",
    "edu.point1.desc": "But we usually think in GB. 1 GB = 1024 MB (binary, as Windows uses).",
    "edu.point2.title": "\"Available shrink space\" is NOT the free space on C:",
    "edu.point2.desc": "It's the maximum amount Windows can shrink right now, limited by unmovable files (page file, hibernation, MFT, etc.).",
    "edu.point3.title": "You decide how much to shrink",
    "edu.point3.desc": "You can type a smaller number than the maximum. That unallocated space is where Linux will be installed.",
    "edu.note.title": "Important note:",
    "edu.note.text": "This simulator does NOT modify your disk. It only does the math so you can understand the numbers before clicking \"Shrink\" in Windows.",
    "edu.details.title": "More details on what limits shrinking",
    "edu.details.intro": "Windows cannot move certain files while the system is running. These \"unmovable\" files set the limit for how far the partition can shrink. Common examples:",
