    "edu.guideTitle": "Guide: “Shrink Volume” (Windows)",
    "guide.what.title": "What is “Shrink Volume”?",
    "guide.what.desc": "The <b>Shrink Volume</b> option lets you reduce the size of an existing partition (for example, the <b>C:</b> drive) to leave <b>unallocated space</b> on the disk.",
    "guide.what.list.0": "Install another operating system (such as Linux).",
    "guide.what.list.1": "Create a new partition for data.",
    "guide.what.list.2": "Separate the system from your personal files.",
    "guide.what.list.3": "Better organize the disk.",
    "guide.what.note": "<b>It does not delete files automatically</b>, but it is always advisable to make a backup beforehand.",
    "guide.before.title": "Total size before the shrink (in MB)",
    "guide.before.desc": "This is the current size of the partition before making any changes.",
    "guide.available.title": "Available shrink space (in MB)",
    "guide.available.desc1": "This point confuses a lot of people: <b>it is not the total free space</b>.",
    "guide.available.desc2": "It is the <b>maximum Windows allows you to shrink at that moment</b> (maximum allowed). Sometimes this maximum is smaller than expected because Windows cannot move certain system files while they are in use (paging, hibernation, restore points, etc.).",
    "guide.desired.title": "Size of the space you want to shrink (in MB)",
    "guide.desired.desc1": "Here you decide how much to shrink. You can type a value <b>equal to or lower than</b> the “Available shrink space”.",
