    "howto.step3.title": "📊 Step 3 — Understand the disk bar",
    "howto.step3.p1": "Once you have entered the first two values:",
    "howto.step3.p2": "The simulated disk bar appears on the right.",
    "howto.step3.p3": "On that bar you will see:",
    "howto.step3.list.0": "🔵 Blue area → Windows (after)",
    "howto.step3.list.1": "⚪ Striped gray area → Free space for Linux",
    "howto.step3.list.2": "🎚️ A small slider control (the divider)",
    "howto.step3.p4": "That small control is called: Partition divider (or simply divider / handle in technical terms).",
    "howto.handle.title": "🎚️ How to move the divider correctly",
    "howto.handle.list.0": "Click on the divider.",
    "howto.handle.list.1": "Keep the mouse button held down.",
    "howto.handle.list.2": "Drag it to the right.",
    "howto.handle.p1": "❗ You will not be able to move it to the left beyond the limit (You cannot shrink the assigned space beyond the point where the unmovable files are located).",
    "howto.why.title": "❓ Why can’t it be moved to the left?",
    "howto.why.p1": "Because Windows has already done its internal calculation.",
    "howto.why.p2": "Windows scans the disk and detects files that cannot be moved, for example:",
    "howto.why.list.0": "Paging file (pagefile.sys)",
    "howto.why.list.1": "Hibernation",
    "howto.why.list.2": "System metadata",
    "howto.why.list.3": "Non-relocatable fragments",
    "howto.why.list.4": "Internal NTFS structures",
    "howto.why.p3": "That is why a maximum limit appears.",
    "howto.why.p4": "That limit is exactly the value Windows shows as: “Available shrink space”",
    "howto.why.p5": "That number is the maximum Windows allows you to shrink at that moment.",
    "howto.thirdparty.p1": "Unless... you use third-party partitioning software that can shrink a volume or partition containing unmovable files (it moves them automatically) through the Resize Partition feature, as <a href=\"https://www.diskpart.com/es/articles/reducir-volumen-con-archivos-inamovibles-7400-tc.html\" target=\"_blank\">AOMEI Partition Assistant</a> does.",
    "howto.thirdparty.p2": "However, for inexperienced people this can be dangerous, and I do not want to lead them into doing things they do not understand the risks of. That is a program I list here because I have used it myself, but to use it you need to understand well what is being done, you need proper training, and it is essential to make a backup. On YouTube there are videos explaining how to use it. What I do not like is that it takes a long time throughout the shrinking process, and it is faster to use Windows’ own program.",
