    "howto.concept.title": "📘 Important concept",
    "howto.concept.p1": "Many people believe that if they have, for example:",
    "howto.concept.p2": "Free space: 250 GB",
    "howto.concept.p3": "They will be able to shrink the full 250 GB.",
    "howto.concept.p4": "Windows does not only look at how much free space there is. It also checks where the files are located inside the disk. If there are important files at the end of the disk, it cannot shrink beyond them.",
    "howto.concept.p5": "That is what this simulator helps you understand visually.",
    "ms.title": "⚠️ Explanation of Microsoft’s official warning",
    "ms.p1": "The <a href=\"https://learn.microsoft.com/windows-server/storage/disk-management/shrink-a-basic-volume\" target=\"_blank\">Microsoft documentation</a> includes the following warning:",
    "ms.quote": "“If the partition is an unformatted partition that contains data, such as a database file, shrinking it could destroy the data”.",
    "ms.p2": "What does this mean?",
    "ms.p3": "This warning refers specifically to unformatted partitions that Windows cannot recognize, that is, it does not refer to the “C: drive” that a normal user works with, but to another partition that is not formatted as NTFS.",
    "ms.p4": "Typical example on servers:",
    "ms.example.list.0": "The administrator creates an additional disk.",
    "ms.example.list.1": "That disk is NOT formatted with NTFS.",
    "ms.example.list.2": "It is handed directly to the database engine.",
    "ms.example.list.3": "SQL Server writes data directly at the block level.",
    "ms.p5": "In that case:",
    "ms.raw.list.0": "Windows sees no files.",
    "ms.raw.list.1": "There is no MFT (Master File Table).",
    "ms.raw.list.2": "There is no NTFS structure.",
    "ms.raw.list.3": "The volume appears as RAW.",
    "ms.p6": "But SQL Server does know which blocks contain data.",
    "ms.p7": "An unformatted partition is a partition that:",
    "ms.unformatted.list.0": "Does not use a recognized file system (NTFS, FAT32, exFAT).",
    "ms.unformatted.list.1": "Is used directly by specialized software at the block level.",
    "ms.unformatted.list.2": "Uses a format that Windows cannot recognize (which can also be Linux partitions, e.g. ext4, and others).",
    "ms.p8": "Why could shrinking destroy data?",
    "ms.p9": "When shrinking a normal NTFS partition, Windows:",
    "ms.ntfs.list.0": "Reads the file system metadata (MFT).",
    "ms.ntfs.list.1": "Knows where the files are located.",
    "ms.ntfs.list.2": "Moves the movable files if necessary.",
    "ms.ntfs.list.3": "Reduces the size of the partition safely.",
    "ms.p10": "However, on a RAW partition:",
    "ms.raw2.list.0": "There is no file system structure.",
    "ms.raw2.list.1": "Windows cannot identify which blocks contain critical data.",
    "ms.raw2.list.2": "The shrink operation may run through blocks of active data.",
    "ms.raw2.list.3": "This can cause irreversible data loss.",
    "ms.p11": "Does this apply to typical home users?",
    "ms.p12": "If you are shrinking:",
    "ms.home.list.0": "The Windows system partition (C:)",
    "ms.home.list.1": "A standard NTFS data partition",
    "ms.p13": "This warning does not apply.",
    "ms.p14": "It mainly refers to:",
    "ms.who.list.0": "Database servers that use raw storage",
    "ms.who.list.1": "Industrial systems",
    "ms.who.list.2": "Embedded systems",
    "ms.who.list.3": "Specialized storage configurations",
    "ms.p15": "Recommended practice",
    "ms.best.list.0": "Back up important data (e.g. thesis, assignments, homework, reports, journals, audio and video edits, etc.).",
    "ms.best.list.1": "Make sure the system is stable.",
    "ms.best.list.2": "Avoid power interruptions during the operation.",
    "ms.p16": "Changes to the disk partition modify the structure of the storage device, and unexpected failures (such as a power cut) can cause damage.",
    "ms.p17": "If the power goes out while Windows is shrinking the volume:",
    "ms.power.list.0": "The system might fail to boot.",
    "ms.power.list.1": "The partition could be damaged.",
    "ms.power.list.2": "Files could be lost.",
    "ms.p18": "That is why it is recommended:",
    "ms.recommend.list.0": "Use a laptop with a charged battery.",
    "ms.recommend.list.1": "Or have a UPS if it is a desktop computer."
