    "lang.select": "Idioma",
    "lang.current": "Idioma atual",
    "lang.native": "Nome nativo",
    "btn.reduce": "Reduzir",
    "btn.cancel": "Cancelar",
    "btn.reduceFake": "Este botão deve ser clicado no seu Windows real.",
    "dm.title": "Gerenciador de Discos (simulação)",
    "result.windowsAfterVal": "—",
    "result.linuxSpaceVal": "—",
    "tip.tip": "Dica:",
    "tip.tipDesc": "Arraste o divisor ou digite o valor de “Espaço a reduzir”.",
    "tip.rule": "Regra principal:",
    "tip.ruleDesc": "Nunca será possível exceder o “Espaço disponível para redução”.",
    "edu.guideTitle": "Guia: “Reduzir Volume” (Windows)",
    "guide.what.title": "O que é “Reduzir Volume”?",
    "guide.what.desc": "A opção <b>Reduzir Volume</b> permite diminuir o tamanho de uma partição existente (por exemplo, a unidade <b>C:</b>) para deixar <b>espaço não alocado</b> no disco.",
    "guide.what.list.0": "Instalar outro sistema operacional (como o Linux).",
    "guide.what.list.1": "Criar uma nova partição para dados.",
    "guide.what.list.2": "Separar o sistema dos arquivos pessoais.",
    "guide.what.list.3": "Organizar melhor o disco.",
    "guide.what.note": "<b>Não apaga arquivos automaticamente</b>, mas sempre é recomendável fazer um backup antes.",
    "guide.before.title": "Tamanho total antes da redução (em MB)",
    "guide.before.desc": "É o tamanho atual da partição antes de fazer qualquer alteração.",
    "guide.available.title": "Espaço disponível para a redução (em MB)",
    "guide.available.desc1": "Este ponto confunde muita gente: <b>não é o espaço livre total</b>.",
    "guide.available.desc2": "É o <b>máximo que o Windows permite reduzir naquele momento</b> (máximo permitido). Às vezes esse máximo é menor do que se espera porque o Windows não consegue mover certos arquivos do sistema enquanto estão em uso (paginação, hibernação, restauração, etc.).",
    "guide.desired.title": "Tamanho do espaço que deseja reduzir (em MB)",
    "guide.desired.desc1": "Aqui você decide quanto quer reduzir. Pode digitar um valor <b>igual ou menor</b> que o “Espaço disponível para a redução”.",
    "guide.desired.desc2": "Tudo o que você reduzir ficará como <b>espaço não alocado</b>.",
    "guide.desired.desc3": "Nesta página, o painel <b>“Gerenciador de Discos (simulação)”</b> também mostra o valor em <b>GB</b> para facilitar a compreensão.",
    "guide.after.title": "Tamanho total depois da redução (em MB)",
    "guide.after.desc1": "É o tamanho com o qual a partição ficará depois da redução.",
    "guide.after.desc2": "<b>Tamanho antes</b> − <b>Tamanho a reduzir</b> = <b>Tamanho depois</b> (e na simulação você também verá em GB).",
    "guide.after2.title": "O que acontece depois de “Reduzir”?",
    "guide.after2.desc1": "No Windows aparecerá um bloco em preto chamado <b>“Espaço não alocado”</b>.",
    "guide.after2.desc2": "Você pode criar uma nova partição ali ou deixar assim para que o instalador do Linux use esse espaço durante a instalação.",
    "guide.important.title": "Importante:",
    "guide.important.desc": "Esta página não faz alterações reais no seu disco. Ela apenas simula números e proporções.",
    "howto.title": "🖥️ Como usar o simulador (com explicações muito detalhadas)",
    "howto.step1.title": "📌 Passo 1 — Abrir o Windows",
    "howto.step1.p1": "No seu computador:",
    "howto.step1.list.0": "Pressione Win + X",
    "howto.step1.list.1": "Selecione Gerenciamento de Disco",
    "howto.step1.list.2": "Clique com o botão direito na partição do Windows (C:)",
    "howto.step1.list.3": "Selecione Reduzir Volume…",
    "howto.step1.p2": "O Windows mostrará uma janela com 3 valores importantes.",
    "howto.step2.title": "📋 Passo 2 — Copiar os dois primeiros valores",
    "howto.step2.p1": "Você deve copiá-los exatamente (em MB e sem pontos ou vírgulas):",
    "howto.step2.list.0": "✅ Tamanho total antes da redução",
    "howto.step2.list.1": "✅ Espaço disponível para a redução",
    "howto.step2.p2": "Você informa esses dois valores no simulador web.",
    "howto.step3.title": "📊 Passo 3 — Entender a barra do disco",
    "howto.step3.p1": "Depois de informar os dois primeiros valores:",
    "howto.step3.p2": "À direita aparece a barra de disco simulada.",
    "howto.step3.p3": "Nessa barra você verá:",
    "howto.step3.list.0": "🔵 Área azul → Windows (depois)",
    "howto.step3.list.1": "⚪ Área cinza listrada → Espaço vazio para o Linux",
    "howto.step3.list.2": "🎚️ Um pequeno controle deslizante (o divisor)",
    "howto.step3.p4": "Esse pequeno controle se chama: <b>Divisor de partição</b> (ou simplesmente divisor / handle em termos técnicos).",
    "howto.handle.title": "🎚️ Como mover o divisor corretamente",
    "howto.handle.list.0": "Clique sobre o divisor.",
    "howto.handle.list.1": "Mantenha o botão do mouse pressionado.",
    "howto.handle.list.2": "Arraste-o para a direita.",
    "howto.handle.p1": "❗ Você não poderá movê-lo para a esquerda além do limite (Não é possível reduzir o espaço alocado além do ponto em que estão os arquivos não móveis).",
    "howto.why.title": "❓ Por que não é possível movê-lo para a esquerda?",
    "howto.why.p1": "Porque o Windows já fez o cálculo interno.",
    "howto.why.p2": "O Windows analisa o disco e detecta arquivos que <b>não podem ser movidos</b>, por exemplo:",
    "howto.why.list.0": "Arquivo de paginação (<code>pagefile.sys</code>)",
    "howto.why.list.1": "Hibernação",
    "howto.why.list.2": "Metadados do sistema",
    "howto.why.list.3": "Fragmentos não relocáveis",
    "howto.why.list.4": "Estruturas internas do sistema NTFS",
    "howto.why.p3": "É por isso que aparece um limite máximo.",
    "howto.why.p4": "Esse limite é exatamente o valor que o Windows mostra como:<br/><b>“Espaço disponível para a redução”</b>",
    "howto.why.p5": "Esse número é o máximo que o Windows permite reduzir naquele momento.",
    "howto.thirdparty.p1": "<b>Exceto que.-</b> você use um software de particionamento de terceiros que consegue reduzir um volume ou partição com arquivos inamovíveis (ele os move automaticamente) por meio da função Redimensionar partição, como faz o <a href=\"https://www.diskpart.com/es/articles/reducir-volumen-con-archivos-inamovibles-7400-tc.html\" target=\"_blank\">AOMEI Partition Assistant</a>.",
    "howto.thirdparty.p2": "Mas sem embargo, isso pode ser perigoso para pessoas sem experiência, e não quero levar pessoas a fazerem coisas sem entenderem os riscos. Esse é um programa que listo aqui porque eu mesmo já o usei, mas para usá-lo é preciso entender bem o que está sendo feito, é preciso ter treinamento, e é essencial fazer um backup. No YouTube há vídeos explicando como usá-lo. O que eu não gosto é que ele demora muito durante todo o processo de redução, e é mais rápido usar o próprio programa do Windows.",
    "howto.copy.title": "📋 Botão “Copiar”",
    "howto.copy.p1": "O campo:",
    "howto.copy.quote": "“Tamanho do espaço que deseja reduzir, em MB”",
    "howto.copy.p2": "inclui um botão <b>Copiar</b>.",
    "howto.copy.list.0": "Copia o valor automaticamente para a área de transferência.",
    "howto.copy.list.1": "Permite colar diretamente na janela real do Windows.",
