    "howto.mobile.list.0": "Em computadores → é exibido em duas colunas.",
    "howto.mobile.list.1": "No celular → tudo é exibido em uma única coluna.",
    "howto.mobile.p1": "Primeiro aparece o simulador e abaixo o resultado.",
    "howto.built.title": "🛠️ Como foi construído",
    "howto.built.list.0": "HTML",
    "howto.built.list.1": "CSS (estilo visual tipo Windows 10)",
    "howto.built.list.2": "JavaScript (lógica do divisor e cálculos)",
    "howto.built.list.3": "Clipboard API para copiar valores",
    "howto.built.p1": "Não requer backend nem instalação.",
    "howto.concept.title": "📘 Conceito importante",
    "howto.concept.p1": "Muitas pessoas acham que, se tiverem por exemplo:",
    "howto.concept.p2": "<b>Espaço livre: 250 GB</b>",
    "howto.concept.p3": "Poderão reduzir 250 GB inteiros.",
    "howto.concept.p4": "O Windows não olha apenas quanto há de espaço livre. Ele também verifica onde os arquivos estão localizados dentro do disco. Se houver arquivos importantes no final do disco, não poderá reduzir além deles.",
    "howto.concept.p5": "É exatamente isso que este simulador ajuda a entender visualmente.",
    "ms.title": "⚠️ Explicação do aviso oficial da Microsoft",
    "ms.p1": "A <a href=\"https://learn.microsoft.com/windows-server/storage/disk-management/shrink-a-basic-volume\" target=\"_blank\">documentação da Microsoft</a> inclui o seguinte aviso:",
    "ms.quote": "“Se a partição for uma partição não formatada que contém dados, como um arquivo de banco de dados, reduzi-la pode destruir os dados”.",
    "ms.p2": "<b>O que isso significa?</b>",
    "ms.p3": "Este aviso se refere especificamente a partições não formatadas reconhecíveis pelo Windows, ou seja, não se refere ao “Disco C:” que um usuário comum usa, mas a outra partição que não está formatada como NTFS",
    "ms.p4": "<b>Exemplo típico em servidores:</b>",
    "ms.example.list.0": "O administrador cria um disco adicional.",
    "ms.example.list.1": "Esse disco NÃO é formatado com NTFS.",
    "ms.example.list.2": "Ele é entregue diretamente ao mecanismo de banco de dados.",
    "ms.example.list.3": "O SQL Server grava dados diretamente no nível de blocos.",
    "ms.p5": "Nesse caso:",
    "ms.raw.list.0": "O Windows não vê arquivos.",
    "ms.raw.list.1": "Não há MFT (Tabela Mestre de Arquivos)",
    "ms.raw.list.2": "Não há estrutura NTFS.",
    "ms.raw.list.3": "O volume aparece como RAW.",
    "ms.p6": "Mas o SQL Server sabe quais blocos contêm dados.",
    "ms.p7": "Uma partição não formatada é uma partição que:",
    "ms.unformatted.list.0": "Não usa um sistema de arquivos reconhecido (NTFS, FAT32, exFAT).",
    "ms.unformatted.list.1": "É usada diretamente por software especializado em nível de blocos.",
    "ms.unformatted.list.2": "Usa um formato que o Windows não reconhece (o que também pode ser partições do Linux, por exemplo ext4, e outras).",
    "ms.p8": "<b>Por que a redução poderia destruir dados?</b>",
    "ms.p9": "Ao reduzir uma partição NTFS normal, o Windows:",
    "ms.ntfs.list.0": "Lê os metadados do sistema de arquivos (MFT).",
    "ms.ntfs.list.1": "Sabe onde os arquivos estão localizados.",
    "ms.ntfs.list.2": "Move os arquivos móveis, se necessário.",
    "ms.ntfs.list.3": "Reduz o tamanho da partição com segurança.",
    "ms.p10": "No entanto, em uma partição RAW:",
    "ms.raw2.list.0": "Não existe uma estrutura de sistema de arquivos.",
    "ms.raw2.list.1": "O Windows não consegue identificar quais blocos contêm dados críticos.",
    "ms.raw2.list.2": "A operação de redução pode atravessar blocos de dados ativos.",
    "ms.raw2.list.3": "Isso pode causar perda irreversível de dados.",
    "ms.p11": "<b>Isso se aplica a usuários domésticos típicos?</b>",
    "ms.p12": "Se você está reduzindo:",
    "ms.home.list.0": "A partição do sistema Windows (C:)",
    "ms.home.list.1": "Uma partição de dados NTFS padrão",
    "ms.p13": "Este aviso não se aplica.",
    "ms.p14": "Ele se refere principalmente a:",
    "ms.who.list.0": "Servidores de banco de dados que utilizam armazenamento bruto",
    "ms.who.list.1": "Sistemas industriais",
    "ms.who.list.2": "Sistemas embarcados",
    "ms.who.list.3": "Configurações de armazenamento especializadas",
    "ms.p15": "<b>Prática recomendada</b>",
    "ms.best.list.0": "Faça um backup dos dados importantes (ex.: tese, trabalhos, lições de casa, projetos, diários, edições de áudio e vídeo, etc.).",
    "ms.best.list.1": "Garanta a estabilidade do sistema.",
    "ms.best.list.2": "Evite interrupções de energia durante a operação.",
    "ms.p16": "As alterações na partição do disco modificam a estrutura do dispositivo de armazenamento, e falhas inesperadas (como uma queda de energia) podem causar danos.",
    "ms.p17": "Se a energia acabar enquanto o Windows está reduzindo o volume:",
    "ms.power.list.0": "O sistema pode não iniciar.",
    "ms.power.list.1": "A partição pode ser danificada.",
    "ms.power.list.2": "Arquivos podem ser perdidos.",
    "ms.p18": "Por isso é recomendável:",
    "ms.recommend.list.0": "Usar um notebook com a bateria carregada.",
    "ms.recommend.list.1": "Ou ter um no-break (UPS) se for um computador de mesa."
