    "edu.best.warning": "Изменения разделов диска модифицируют структуру накопителя, и непредвиденные сбои (например, отключение питания) могут вызвать повреждение.",
    "edu.best.powerLoss": "Если питание отключится, пока Windows сжимает том:",
