    "edu.guideTitle": "Руководство: «Сжать том» (Windows)",
    "guide.what.title": "Что такое «Сжать том»?",
    "guide.what.desc": "Опция <b>Сжать том</b> позволяет уменьшить размер существующего раздела (например, диска <b>C:</b>), оставив на диске <b>неразмеченное пространство</b>.",
    "guide.what.list.0": "Установить другую операционную систему (например, Linux).",
    "guide.what.list.1": "Создать новый раздел для данных.",
    "guide.what.list.2": "Отделить систему от личных файлов.",
    "guide.what.list.3": "Лучше организовать диск.",
    "guide.what.note": "<b>Файлы автоматически не удаляются</b>, но всегда рекомендуется сначала сделать резервную копию.",
    "guide.before.title": "Общий размер до сжатия (в МБ)",
    "guide.before.desc": "Это текущий размер раздела до внесения изменений.",
    "guide.available.title": "Доступное для сжатия пространство (в МБ)",
    "guide.available.desc1": "Этот момент сбивает с толку многих: <b>это не всё свободное пространство</b>.",
    "guide.available.desc2": "Это <b>максимум, на который Windows позволяет сжать прямо сейчас</b> (допустимый максимум). Иногда этот максимум меньше ожидаемого, потому что Windows не может переместить некоторые системные файлы, пока они используются (файл подкачки, гибернация, точки восстановления и т. д.).",
    "guide.desired.title": "Размер пространства, которое вы хотите сжать (в МБ)",
    "guide.desired.desc1": "Здесь вы решаете, на сколько уменьшить. Можно ввести значение <b>равное или меньше</b>, чем «Доступное для сжатия пространство».",
    "guide.desired.desc2": "Всё, что вы сожмёте, останется как <b>неразмеченное пространство</b>.",
    "guide.desired.desc3": "На этой странице панель <b>«Диспетчер дисков (симуляция)»</b> также показывает значение в <b>ГБ</b>, чтобы было проще понять.",
    "guide.after.title": "Общий размер после сжатия (в МБ)",
    "guide.after.desc1": "Это размер, который останется у раздела после сжатия.",
    "guide.after.desc2": "<b>Размер до</b> − <b>Размер сжатия</b> = <b>Размер после</b> (и в симуляции это также видно в ГБ).",
    "guide.after2.title": "Что происходит после «Сжать»?",
    "guide.after2.desc1": "В Windows появится чёрный блок под названием <b>«Неразмеченное пространство»</b>.",
    "guide.after2.desc2": "Можно создать там новый раздел или оставить как есть, чтобы установщик Linux использовал его во время установки.",
    "guide.important.title": "Важно:",
    "guide.important.desc": "Эта страница не вносит реальных изменений на ваш диск. Она только имитирует числа и пропорции.",
    "howto.title": "🖥️ Как пользоваться симулятором (с очень подробными объяснениями)",
