    "howto.step1.list.2": "Щёлкните правой кнопкой по разделу Windows (C:)",
    "howto.step1.list.3": "Выберите «Сжать том…»",
    "howto.step1.p2": "Windows покажет окно с 3 важными значениями.",
    "howto.step2.title": "📋 Шаг 2 — Скопируйте первые два значения",
    "howto.step2.p1": "Копировать нужно точно (в МБ и без точек и запятых):",
    "howto.step2.list.0": "✅ Общий размер до сжатия",
    "howto.step2.list.1": "✅ Доступное для сжатия пространство",
    "howto.step2.p2": "Эти два значения вводятся в веб-симуляторе.",
    "howto.step3.title": "📊 Шаг 3 — Поймите, как работает полоса диска",
