    "howto.thirdparty.p1": "<b>Кроме того,.-</b> если вы используете стороннюю программу для работы с разделами, которая умеет сжимать том или раздел с неперемещаемыми файлами (перемещая их автоматически) с помощью функции «Изменить размер раздела», как это делает <a href=\"https://www.diskpart.com/es/articles/reducir-volumen-con-archivos-inamovibles-7400-tc.html\" target=\"_blank\">AOMEI Partition Assistant</a>.",
    "howto.thirdparty.p2": "Однако для неопытных пользователей это может быть опасно, и я не хочу вести их делать то, риски чего они не понимают. Эта программа указана здесь потому, что я сам ею пользовался, но для её использования нужно хорошо понимать, что происходит, нужна подготовка, и обязательно нужна резервная копия. На YouTube есть видео с объяснением, как ею пользоваться. Что мне не нравится — так это то, что весь процесс сжатия занимает очень много времени, а использовать собственную программу Windows быстрее.",
