    "edu.best.warning": "ディスク パーティションの変更はストレージ デバイスの構造を変更するため、予期せない障害 (停電など) が损働を引き起こす可能性があります。",
    "edu.best.powerLoss": "Windowsがボリュームを縮小中に電源が切れた場合:",
