    "edu.title": "为什么会有这个模拟器？",
    "edu.intro": "想要在 Windows 旺边安装 Linux (双启动) 时、需要在磁盘上腾出空间。 Windows 自带“压缩卷”功能、可以在不删除数据的情况下缩小 C: 分区。但显示的数字容易让人囿惶。",
    "edu.point1.title": "数字单位是 MB (光字节)",
    "edu.point1.desc": "但我们通常用 GB 思考。 1 GB = 1024 MB (二进制、Windows 采用的标准)。",
    "edu.point2.title": "“可用压缩空间”不是 C: 的剩余空间",
    "edu.point2.desc": "它是 Windows 当前能压缩的最大量、受限于无法移动的文件 (页面文件、休眠文件、MFT 等)。",
