    "edu.guideTitle": "指南：“压缩卷”(Windows)",
    "guide.what.title": "什么是“压缩卷”？",
    "guide.what.desc": "<b>压缩卷</b>选项可以减小现有分区的大小（例如 <b>C:</b> 驱动器），从而在磁盘上留下<b>未分配空间</b>。",
    "guide.what.list.0": "安装另一个操作系统（例如 Linux）。",
    "guide.what.list.1": "创建一个用于存储数据的新分区。",
    "guide.what.list.2": "将系统与个人文件分开。",
    "guide.what.list.3": "更好地整理磁盘。",
    "guide.what.note": "<b>它不会自动删除文件</b>，但始终建议事先创建备份。",
    "guide.before.title": "缩减前的总大小（MB）",
    "guide.before.desc": "这是进行更改前分区的当前大小。",
    "guide.available.title": "可用于缩减的空间（MB）",
    "guide.available.desc1": "这一点让很多人困惑：<b>它不是总可用空间</b>。",
    "guide.available.desc2": "它是<b>Windows 当前允许缩减的最大值</b>（最大允许值）。这个最大值有时会比预期小，因为 Windows 在这些文件被使用时无法移动某些系统文件（分页、休眠、还原点等）。",
    "guide.desired.title": "要缩减的空间大小（MB）",
    "guide.desired.desc1": "在这里决定要缩减多少。可以输入<b>小于或等于</b>“可用于缩减的空间”的数值。",
    "guide.desired.desc2": "缩减出来的空间将成为<b>未分配空间</b>。",
    "guide.desired.desc3": "在本页面中，<b>“磁盘管理器（模拟）”</b>面板还会以 <b>GB</b> 显示，便于理解。",
    "guide.after.title": "缩减后的总大小（MB）",
    "guide.after.desc1": "这是缩减后分区将剩下的大小。",
    "guide.after.desc2": "<b>缩减前大小</b> − <b>要缩减的大小</b> = <b>缩减后大小</b>（在模拟中也会看到 GB）。",
    "guide.after2.title": "点击“缩减”之后会发生什么？",
    "guide.after2.desc1": "Windows 中会出现一个名为<b>“未分配空间”</b>的黑色区块。",
    "guide.after2.desc2": "可以在那里创建新分区，或保持原样，让 Linux 安装程序在安装过程中使用它。",
    "guide.important.title": "重要：",
    "guide.important.desc": "此页面不会对您的磁盘进行任何真实更改。它只是模拟数字和比例。",
    "howto.title": "🖥️ 如何使用模拟器（附非常详细的说明）",
    "howto.step1.title": "📌 第 1 步 — 打开 Windows",
    "howto.step1.p1": "在你的电脑上：",
    "howto.step1.list.0": "按 Win + X",
    "howto.step1.list.1": "选择“磁盘管理”",
