    "howto.step1.list.3": "选择“压缩卷…”",
    "howto.step1.p2": "Windows 会显示一个包含 3 个重要数值的窗口。",
    "howto.step2.title": "📋 第 2 步 — 复制前两个数值",
    "howto.step2.p1": "你必须精确复制（单位为 MB，且不带小数点或逗号）：",
    "howto.step2.list.0": "✅ 缩减前的总大小",
    "howto.step2.list.1": "✅ 可用于缩减的空间",
    "howto.step2.p2": "把这两个数值输入到网页模拟器中。",
    "howto.step3.title": "📊 第 3 步 — 理解磁盘条",
    "howto.step3.p1": "输入前两个数值之后：",
