    "howto.step3.p3": "在该磁盘条上你会看到：",
    "howto.step3.list.0": "🔵 蓝色区域 → Windows（缩减后）",
    "howto.step3.list.1": "⚪ 灰色条纹区域 → Linux 用的空闲空间",
    "howto.step3.list.2": "🎚️ 一个小滑块（分隔条）",
    "howto.step3.p4": "这个小控件称为：<b>分区分隔条</b>（技术上简称 divider / handle）。",
    "howto.handle.title": "🎚️ 如何正确拖动分隔条",
    "howto.handle.list.0": "点击分隔条。",
    "howto.handle.list.1": "保持鼠标按键按下。",
    "howto.handle.list.2": "向右拖动。",
    "howto.handle.p1": "❗ 你无法把它向左拖过上限（无法将分配的空间缩减到不可移动文件所在位置之后）。",
    "howto.why.title": "❓ 为什么不能向左拖动？",
    "howto.why.p1": "因为 Windows 已经完成了内部计算。",
    "howto.why.p2": "Windows 会扫描磁盘并检测<b>无法移动</b>的文件，例如：",
    "howto.why.list.0": "页面文件 (<code>pagefile.sys</code>)",
    "howto.why.list.1": "休眠文件",
    "howto.why.list.2": "系统元数据",
    "howto.why.list.3": "不可重定位的片段",
    "howto.why.list.4": "NTFS 内部结构",
    "howto.why.p3": "因此会出现一个最大上限。",
    "howto.why.p4": "这个上限正是 Windows 显示为下列内容的数值：<br/><b>“可用于缩减的空间”</b>",
    "howto.why.p5": "这个数值就是此刻 Windows 允许缩减的最大量。",
    "howto.thirdparty.p1": "<b>除非——</b>你使用了第三方分区软件，它能通过“调整分区大小”功能缩减含有不可移动文件的卷或分区（它会自动移动这些文件），就像 <a href=\"https://www.diskpart.com/es/articles/reducir-volumen-con-archivos-inamovibles-7400-tc.html\" target=\"_blank\">AOMEI Partition Assistant</a> 那样。",
    "howto.thirdparty.p2": "不过，对没有经验的人来说这可能很危险，我不想让他们在不了解风险的情况下就去做这些事。我把那个程序放在这里，是因为我自己用过它；但要使用它，必须充分理解它的操作，需要接受培训，而且绝对要先做备份。YouTube 上有讲解如何使用的视频。我不太喜欢的是，整个缩减过程耗时很长，用 Windows 自带的程序反而更快。",
    "howto.copy.title": "📋 “复制”按钮",
    "howto.copy.p1": "这个输入框：",
    "howto.copy.quote": "“要缩减的空间大小（MB）”",
