    "instructions.text": "<b>說明:</b> 開啟磁碟管理 → 右鍵點擊 Windows 分割區 (C:) → 壓縮磁碟區… 完全按原樣複製前兩個數字 (MB 單位、無逗號或點號)。然後調整想要壓縮的大小、查看右側結果。",
