    "msg.invalidTotal": "請為“壓縮前總大小”輸入有效數字。",
    "msg.invalidAvailable": "“可用壓縮空間”必须為正數。",
    "msg.desiredExceeds": "期待壓縮大小不能超過可用壓縮空間。",
    "msg.copied": "已複製: {value} (MB)。现在可以在 Windows 中貼上。",
