    "edu.guideTitle": "دليل: “تصغير الحجم” (Windows)",
    "guide.what.title": "ما هو «تصغير الحجم»؟",
    "guide.what.desc": "يتيح لك خيار <b>تصغير الحجم</b> تقليل حجم قسم موجود (مثل محرك <b>C:</b>)، فتترك مساحة <b>غير مخصصة</b> على القرص.",
    "guide.what.list.0": "تثبيت نظام تشغيل آخر (مثل لينكس).",
    "guide.what.list.1": "إنشاء قسم جديد للبيانات.",
    "guide.what.list.2": "فصل النظام عن الملفات الشخصية.",
    "guide.what.list.3": "تنظيم القرص بشكل أفضل.",
    "guide.what.note": "<b>لا يحذف الملفات تلقائيًا</b>، لكن يُنصح دائمًا بإجراء نسخة احتياطية قبل ذلك.",
    "guide.before.title": "الحجم الكلي قبل التصغير (بالميغابايت)",
    "guide.before.desc": "هذا هو الحجم الحالي للقسم قبل إجراء أي تغييرات.",
    "guide.available.title": "المساحة المتاحة للتصغير (بالميغابايت)",
    "guide.available.desc1": "هذه النقطة تربك كثيرًا: <b>ليست المساحة الحرة الإجمالية</b>.",
    "guide.available.desc2": "إنه <b>أقصى مقدار يسمح به Windows للتصغير في الوقت الحالي</b> (الحد الأقصى المسموح). أحيانًا يكون هذا الحد أصغر من المتوقع لأن Windows لا يستطيع نقل بعض ملفات النظام أثناء استخدامها (الترقيم الاحتياطي، السكون، نقاط الاستعادة، وما إلى ذلك).",
    "guide.desired.title": "حجم المساحة التي تريد تصغيرها (بالميغابايت)",
    "guide.desired.desc1": "هنا تقرر مقدار ما تريد تصغيره. يمكنك إدخال قيمة <b>تساوي أو أقل من</b> «المساحة المتاحة للتصغير».",
    "guide.desired.desc2": "كل ما تصغّره سيبقى كـ <b>مساحة غير مخصصة</b>.",
    "guide.desired.desc3": "في هذه الصفحة تعرض لوحة <b>«مدير الأقراص (محاكاة)»</b> القيمة أيضًا بوحدة <b>جيجابايت</b> لتسهيل الفهم.",
    "guide.after.title": "الحجم الكلي بعد التصغير (بالميغابايت)",
    "guide.after.desc1": "هذا هو الحجم الذي سيصبح عليه القسم بعد التصغير.",
    "guide.after.desc2": "<b>الحجم قبل</b> − <b>الحجم المراد تصغيره</b> = <b>الحجم بعد</b> (وفي المحاكاة تراه أيضًا بالجيجابايت).",
    "guide.after2.title": "ماذا يحدث بعد «تصغير»؟",
    "guide.after2.desc1": "في Windows ستظهر كتلة سوداء تسمى <b>«المساحة غير المخصصة»</b>.",
    "guide.after2.desc2": "يمكنك إنشاء قسم جديد هناك، أو تركه كما هو ليستخدمه مثبّت لينكس أثناء التثبيت.",
    "guide.important.title": "مهم:",
    "guide.important.desc": "هذه الصفحة لا تُجري أي تغييرات حقيقية على قرصك. إنها تحاكي الأرقام والنسب فقط.",
