    "howto.why.p5": "هذا الرقم هو أقصى ما يسمح به Windows للتصغير في الوقت الحالي.",
    "howto.thirdparty.p1": "<b>إلا إذا.-</b> استخدمت برنامج تقسيم من طرف ثالث قادر على تصغير وحدة تخزين أو قسم يحتوي ملفات غير قابلة للنقل (فهو ينقلها تلقائيًا) عبر ميزة «تغيير حجم القسم»، كما يفعل <a href=\"https://www.diskpart.com/es/articles/reducir-volumen-con-archivos-inamovibles-7400-tc.html\" target=\"_blank\">AOMEI Partition Assistant</a>.",
    "howto.thirdparty.p2": "لكن بالنسبة لشخص بلا خبرة قد يكون هذا خطيرًا، ولا أريد أن أقود الناس إلى فعل أشياء دون فهم المخاطر. أذكر هذا البرنامج هنا لأنني استخدمته بنفسي، لكن لاستخدامه عليك فهم جيد لما سيحدث، ويحتاج إلى تدريب، ومن الضروري أخذ نسخة احتياطية. هناك على YouTube فيديوهات تشرح طريقة استخدامه. ما لا يعجبني هو أن العملية كلها تستغرق وقتًا طويلًا، والأسرع استخدام برنامج Windows نفسه.",
    "howto.copy.title": "📋 زر «نسخ»",
    "howto.copy.p1": "الحقل:",
    "howto.copy.quote": "«حجم المساحة التي تريد تصغيرها، بالميجابايت»",
    "howto.copy.p2": "يحتوي على زر <b>نسخ</b>.",
    "howto.copy.list.0": "ينسخ القيمة تلقائيًا إلى الحافظة.",
    "howto.copy.list.1": "يتيح لك لصقها مباشرة في نافذة Windows الحقيقية.",
    "howto.mobile.title": "📱 الاستخدام على الجوال",
    "howto.mobile.list.0": "على الحاسوب → يُعرض في عمودين.",
    "howto.mobile.list.1": "على الهاتف → يُعرض كل شيء في عمود واحد.",
    "howto.mobile.p1": "يظهر المحاكي أولًا وتظهر النتيجة أسفله.",
    "howto.built.title": "🛠️ كيف بُني",
    "howto.built.list.0": "HTML",
    "howto.built.list.1": "CSS (نمط بصري على طراز Windows 10)",
    "howto.built.list.2": "JavaScript (منطق الفاصل والحسابات)",
    "howto.built.list.3": "Clipboard API لنسخ القيم",
    "howto.built.p1": "لا يحتاج إلى خادم خلفي ولا إلى تثبيت.",
    "howto.concept.title": "📘 مفهوم مهم",
    "howto.concept.p1": "يعتقد كثيرون أنه إذا كان لديهم مثلًا:",
    "howto.concept.p2": "<b>مساحة حرة: 250 غيغابايت</b>",
    "howto.concept.p3": "فيستطيعون تصغير 250 غيغابايت كاملة.",
    "howto.concept.p4": "لا ينظر Windows إلى المساحة الحرة فحسب، بل يفحص أيضًا أين توجد الملفات داخل القرص. وإذا وجدت ملفات مهمة في نهاية القرص فلن يستطيع التصغير أبعد منها.",
    "howto.concept.p5": "وهذا بالضبط ما يساعدك على فهمه بصريًا هذا المحاكي.",
    "ms.title": "⚠️ شرح تحذير Microsoft الرسمي",
    "ms.p1": "يتضمن <a href=\"https://learn.microsoft.com/windows-server/storage/disk-management/shrink-a-basic-volume\" target=\"_blank\">توثيق Microsoft</a> التحذير التالي:",
    "ms.quote": "«إذا كان القسم قسمًا غير مُهيأ يحتوي على بيانات، مثل ملف قاعدة بيانات، فإن تصغيره قد يدمر البيانات».",
    "ms.p2": "<b>ماذا يعني هذا؟</b>",
    "ms.p3": "يشير هذا التحذير تحديدًا إلى الأقسام غير المهيأة التي لا يتعرف عليها Windows، أي أنه لا يتعلق بـ«قرص C:» الذي يستخدمه المستخدم العادي، بل بقسم آخر غير مهيأ بصيغة NTFS",
    "ms.p4": "<b>مثال نموذجي على الخوادم:</b>",
    "ms.example.list.0": "ينشئ المسؤول قرصًا إضافيًا.",
