    "ms.ntfs.list.2": "نقل الملفات القابلة للنقل عند الحاجة.",
    "ms.ntfs.list.3": "تقليل حجم القسم بأمان.",
    "ms.p10": "لكن في قسم RAW:",
    "ms.raw2.list.0": "لا توجد بنية نظام ملفات.",
