    "ms.who.list.3": "تكوينات التخزين المتخصصة",
    "ms.p15": "<b>الممارسة الموصى بها</b>",
    "ms.best.list.0": "إنشاء نسخة احتياطية من البيانات المهمة (مثل: الأطروحة، الواجبات، المشاريع، اليوميات، تعديلات الصوت والفيديو، إلخ).",
