    "footer.headline": "क्या सिम्युलेटर ने आपकी मदद की?",
    "footer.desc": "<b>फोर्क</b> करें, अनुवाद करें या प्रोजेक्ट में सुधार करें। योगदान का स्वागत है!",
    "footer.repo": "गिटहब पर स्रोत कोड देखें →",
