    "guide.what.title": "Wat is “Volume verkleinen”?",
    "guide.what.desc": "Met de optie <b>Volume verkleinen</b> kunt u de grootte van een bestaande partitie (bijvoorbeeld de <b>C:</b>-schijf) verkleinen, waardoor er <b>niet-toegewezen ruimte</b> op de schijf overblijft.",
    "guide.what.list.0": "Een ander besturingssysteem installeren (zoals Linux).",
    "guide.what.list.1": "Een nieuwe partitie voor gegevens maken.",
    "guide.what.list.2": "Het systeem scheiden van persoonlijke bestanden.",
    "guide.what.list.3": "De schijf beter organiseren.",
    "guide.what.note": "<b>Het verwijdert geen bestanden automatisch</b>, maar het is altijd verstandig om eerst een back-up te maken.",
    "guide.before.title": "Totale grootte vóór het verkleinen (in MB)",
    "guide.before.desc": "Dit is de huidige grootte van de partitie voordat er wijzigingen worden aangebracht.",
    "guide.available.title": "Beschikbare ruimte om te verkleinen (in MB)",
    "guide.available.desc1": "Dit punt zorgt voor veel verwarring: <b>het is niet de totale vrije ruimte</b>.",
    "guide.available.desc2": "Het is het <b>maximum dat Windows op dit moment mag verkleinen</b> (het toegestane maximum). Dit maximum is soms kleiner dan verwacht, omdat Windows bepaalde systeembestanden niet kan verplaatsen zolang ze in gebruik zijn (wisselbestand, hibernatie, herstelpunten, enz.).",
    "guide.desired.title": "Grootte van de ruimte die u wilt verkleinen (in MB)",
    "guide.desired.desc1": "Hier bepaalt u hoeveel u wilt verkleinen. U kunt een waarde <b>gelijk aan of kleiner dan</b> de “Beschikbare ruimte om te verkleinen” invoeren.",
    "guide.desired.desc2": "Alles wat u verkleinert blijft achter als <b>niet-toegewezen ruimte</b>.",
    "guide.desired.desc3": "Op deze pagina toont het paneel <b>“Schijfbeheer (simulatie)”</b> de waarde ook in <b>GB</b>, zodat ze gemakkelijker te begrijpen is.",
    "guide.after.title": "Totale grootte na het verkleinen (in MB)",
