    "howto.why.p5": "Dat getal is het maximum dat Windows op dit moment mag verkleinen.",
    "howto.thirdparty.p1": "<b>Tenzij.-</b> je partitioneringssoftware van derden gebruikt die een volume of partitie met niet-verplaatsbare bestanden kan verkleinen (ze worden automatisch verplaatst) via de functie Partitiegrootte wijzigen, zoals <a href=\"https://www.diskpart.com/es/articles/reducir-volumen-con-archivos-inamovibles-7400-tc.html\" target=\"_blank\">AOMEI Partition Assistant</a> dat doet.",
    "howto.thirdparty.p2": "Voor mensen zonder ervaring kan dat echter gevaarlijk zijn, en ik wil ze niet naar dingen sturen die ze niet begrijpen. Ik noem dit programma hier omdat ik het zelf heb gebruikt, maar om het te gebruiken moet je goed begrijpen wat er gebeurt, je hebt training nodig, en een back-up is onmisbaar. Op YouTube staan video's die uitleggen hoe je het gebruikt. Wat ik niet prettig vind, is dat het hele proces veel tijd kost, en het sneller is om het eigen programma van Windows te gebruiken.",
    "howto.copy.title": "📋 De knop „Kopiëren”",
