    "howto.built.p1": "Geen backend of installatie nodig.",
    "howto.concept.title": "📘 Belangrijk concept",
    "howto.concept.p1": "Veel mensen denken dat als ze bijvoorbeeld hebben:",
    "howto.concept.p2": "<b>Vrije ruimte: 250 GB</b>",
    "howto.concept.p3": "ze de volledige 250 GB kunnen verkleinen.",
    "howto.concept.p4": "Windows kijkt niet alleen naar de vrije ruimte. Het controleert ook waar de bestanden op de schijf staan. Als er belangrijke bestanden aan het einde van de schijf staan, kan het niet verder verkleinen dan die bestanden.",
    "howto.concept.p5": "Dat is precies wat deze simulator je visueel helpt begrijpen.",
    "ms.title": "⚠️ Uitleg van de officiële Microsoft-waarschuwing",
    "ms.p1": "De <a href=\"https://learn.microsoft.com/windows-server/storage/disk-management/shrink-a-basic-volume\" target=\"_blank\">Microsoft-documentatie</a> bevat de volgende waarschuwing:",
    "ms.quote": "„Als de partitie een ongeformatteerde partitie is die gegevens bevat, zoals een databasebestand, dan kan het verkleinen de gegevens vernietigen”.",
    "ms.p2": "<b>Wat betekent dit?</b>",
    "ms.p3": "Deze waarschuwing gaat specifiek over ongeformatteerde partities die Windows niet kan herkennen, dus niet over het „C:-station” dat een gewone gebruiker hanteert, maar over een andere partitie die niet als NTFS is geformatteerd",
    "ms.p4": "<b>Typisch voorbeeld op servers:</b>",
    "ms.example.list.0": "De beheerder maakt een extra schijf aan.",
    "ms.example.list.1": "Die schijf wordt NIET met NTFS geformatteerd.",
    "ms.example.list.2": "Hij wordt rechtstreeks aan de database-engine gegeven.",
    "ms.example.list.3": "SQL Server schrijft gegevens rechtstreeks op blokniveau.",
